        {"구분":"측량줄", "내용":"정밀한 심판의 도구", "그리스도연결":"공의의 추와 저울로 측량하시는 주 - 그리스도는 완전한 공의의 성취 (사 28:17)"},
        {"구분":"슬퍼하는 성벽", "내용":"피조물의 애도", "그리스도연결":"십자가의 순간 온 땅이 흔들림 - 피조물이 그리스도의 고난에 참여함 (마 27:51)"}
