    "본문": "그 성문들이 땅에 빠짐이여 빗장을 훼파하고 깨뜨리셨으며 그 왕과 방백들이 율법 없는 이방인 중에 있으며 그 선지자들이 여호와의 묵시를 받지 못하는도다",
