        {"항목":"바다 같은 파괴", "내용":"바다는 고대 근동에서 혼돈, 광대함, 경계 없음을 상징. 예루살렘의 파괴가 바다처럼 측량할 수 없음을 표현", "목회적활용":"어떤 고통은 인간의 언어로 측량할 수 없을 만큼 크다"},
        {"항목":"치유자의 부재", "내용":"당시 이스라엘에 인간적인 치유책이 없음. 정치적 동맹도, 군사력도, 경제력도 모두 고갈. 오직 하나님만이 치유의 길", "목회적활용":"절망의 자리가 오직 하나님께만 소망을 두게 하는 자리가 된다"}
