        {"교리":"치유자 하나님", "설명":"'너를 치료하는 여호와임이니라'(출 15:26)는 이름처럼 하나님만이 참된 치유자이심", "관련구절":"출 15:26, 시 147:3, 호 6:1, 사 53:5"},
        {"교리":"절망의 신학", "설명":"인간적 소망의 끝이 신적 소망의 시작. 절망이 신앙의 길로 이끄는 역할", "관련구절":"고후 1:8-9, 시 73:25-26, 욥 13:15, 롬 4:18"}
