        {"원어":"בִּלַּעְנוּ (빌라누)", "의미_문법":"우리가 삼켰다 - 동사 피엘형. 2장의 반복 단어", "설교포인트":"하나님의 도구로 쓰인 자도 자기 공으로 여김"},
        {"원어":"שֶׁקִּוִּינֻהוּ (쉐키비누후)", "의미_문법":"우리가 기다리던 - 동사 피엘형. 오래 바라던 날", "설교포인트":"원수가 오랫동안 복수를 계획하고 있었음"}
