        {"상황":"남의 고난을 기뻐한 자신의 죄를 발견한 분", "성경원리":"이웃의 고난을 기뻐하는 것은 에돔의 죄였고 하나님이 엄히 심판하셨다(옵 1:12)", "실제적용":"깊이 회개하고 자비의 마음을 구하라. 애통하는 자와 함께 애통하는 것이 그리스도의 마음이다"},
        {"상황":"하나님이 나를 잊으신 것 같은 느낌에 시달리는 분", "성경원리":"원수가 '우리가 삼켰다'고 하지만 실은 하나님의 손 안에 있는 일이다. 모든 고난은 섭리 안에 있다", "실제적용":"눈에 보이는 현실 너머의 하나님의 주권을 신뢰하라. 당신의 이야기는 아직 끝나지 않았다"}
