        {"교리":"긍휼의 유보", "설명":"평소 긍휼의 하나님이 긍휼을 거두실 때가 있다. 회개의 기회를 무수히 주시고도 회개하지 않을 때", "관련구절":"잠 1:24-28, 호 11:8, 렘 15:1, 겔 33:11"},
        {"교리":"역사의 주권", "설명":"원수의 뿔이 높아지는 것도 하나님의 주권적 섭리 안에 있음. 일시적 성공도 그분의 허락 안에서만 가능", "관련구절":"단 4:34-35, 사 46:10, 시 75:6-7, 잠 21:1"}
