        {"교리":"지속적 기도", "설명":"하나님은 지속적 간구를 사랑하신다. '쉬지 않는' 기도의 부름", "관련구절":"눅 18:1-8, 살전 5:17, 롬 12:12, 엡 6:18"},
        {"교리":"애통의 회복적 기능", "설명":"회개의 눈물은 정화의 역할을 한다. 마른 종교성이 아닌 눈물 젖은 믿음이 회복을 가져옴", "관련구절":"시 51:17, 요엘 2:12, 마 5:4, 눅 7:38"}
